// The built-in exercise library: 870-odd exercises from free-exercise-db (public domain) with a start
// and end photo each. Data is generated by scripts/exercise-catalog.mjs; photos live in the
// timeo-exercises R2 bucket (public, cached for a year).

export const EXERCISE_IMAGES = process.env.NEXT_PUBLIC_EXERCISE_IMAGES ?? "https://pub-09cf4c88b9e4459fbe63e8bea031041e.r2.dev";

/** Photo `frame` (0 = start, 1 = end) of a catalogue exercise. */
export const exerciseImage = (catalogId: string, frame = 0) => `${EXERCISE_IMAGES}/${catalogId}/${frame}.webp`;

export type CatalogEntry = {
  id: string;
  name: string;
  muscle: string;
  primary: string[];
  secondary: string[];
  equipment: string | null;
  type: "weight" | "bodyweight" | "cardio";
  weightBasis: "total" | "per_hand" | "per_arm";
  unilateral: boolean;
  level: string;
  category: string;
  steps: string[];
  images: number;
};

/** What search needs; src/lib/exercise-catalog-index.json, loaded on demand by the client. */
export type CatalogIndexEntry = Pick<CatalogEntry, "id" | "name" | "muscle" | "equipment" | "images"> & { primary: string | null };

export const loadCatalogIndex = () => import("./exercise-catalog-index.json").then((m) => m.default as CatalogIndexEntry[]);

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();

/** Case and punctuation-blind search over names, target muscle and equipment. The exact name comes
 * first, then names that start with the query, then names holding every word. */
export function searchCatalog<T extends CatalogIndexEntry>(entries: T[], query: string, muscle = "all") {
  const q = norm(query);
  const words = q.split(" ").filter(Boolean);
  const hits = entries.filter((e) => {
    if (muscle !== "all" && e.muscle !== muscle) return false;
    const hay = norm(`${e.name} ${e.primary ?? ""} ${e.equipment ?? ""}`);
    return words.every((w) => hay.includes(w));
  });
  if (!q) return hits;
  const rank = (e: T) => {
    const name = norm(e.name);
    return name === q ? 0 : name.startsWith(q) ? 1 : words.every((w) => name.includes(w)) ? 2 : 3;
  };
  return hits.map((e) => ({ e, r: rank(e) })).sort((a, b) => a.r - b.r).map((x) => x.e);
}
